function cleanLine(b) {
  const l = { ...b };
  if (l.operation && !OPS2.includes(l.operation)) throw bad("Unknown operation " + l.operation);
  if (l.labor_type && !LTYPES.includes(l.labor_type)) throw bad("Unknown labor type " + l.labor_type);
  for (const k of ["qty", "unit_price", "part_cost", "labor_hours", "teardown_hours", "refinish_hours", "sublet_amount", "labor_overlap", "refinish_overlap", "betterment_pct"]) if (l[k] !== void 0 && l[k] !== null && l[k] !== "") {
    l[k] = Number(l[k]);
    if (isNaN(l[k]) || l[k] < 0 || l[k] > 1e6) throw bad("Invalid " + k);
  }
  for (const k of ["markup_pct", "discount_pct"]) if (l[k] !== void 0) {
    if (l[k] === "" || l[k] === null) l[k] = null;
    else {
      l[k] = Number(l[k]);
      if (isNaN(l[k]) || l[k] < -100 || l[k] > 500) throw bad("Invalid " + k);
    }
  }
  if (l.betterment_pct > 100) throw bad("Betterment cannot be over 100%");
  for (const k of ["incl", "judgment", "taxable", "not_included", "reviewed"]) if (l[k] !== void 0) l[k] = l[k] === true || l[k] === 1 || l[k] === "1" || l[k] === "on" ? 1 : 0;
  if (l.paint_stage !== void 0 && !["", "2stage", "3stage", "2tone", null].includes(l.paint_stage)) throw bad("Unknown paint stage");
  if (l.description !== void 0) l.description = String(l.description || "").slice(0, 200);
  return l;
}
